{
  "items": [
    {
      "name": "Rat.den_le_and_le_num_le_of_sub_lt_one_div_den_sq",
      "module_name": "Mathlib.NumberTheory.DiophantineApproximation.Basic",
      "kind": "theorem",
      "type": "∀ {ξ q : ℚ}, |ξ - q| < 1 / ↑q.den ^ 2 → q.den ≤ ξ.den ∧ ⌈ξ * ↑q.den⌉ - 1 ≤ q.num ∧ q.num ≤ ⌊ξ * ↑q.den⌋ + 1"
    },
    {
      "name": "Liouville.exists_pos_real_of_irrational_root",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.Basic",
      "kind": "theorem",
      "type": "∀ {α : ℝ},\n  Irrational α →\n    ∀ {f : Polynomial ℤ},\n      f ≠ 0 →\n        Polynomial.eval α (Polynomial.map (algebraMap ℤ ℝ) f) = 0 →\n          ∃ A, 0 < A ∧ ∀ (a : ℤ) (b : ℕ), 1 ≤ (↑b + 1) ^ f.natDegree * (|α - ↑a / (↑b + 1)| * A)"
    },
    {
      "name": "LindemannWeierstrass.exp_polynomial_approx",
      "module_name": "Mathlib.NumberTheory.Transcendental.Lindemann.AnalyticalPart",
      "kind": "theorem",
      "type": "∀ (f : Polynomial ℤ),\n  Polynomial.eval 0 f ≠ 0 →\n    ∃ c,\n      ∀ p > (Polynomial.eval 0 f).natAbs,\n        Nat.Prime p →\n          ∃ n,\n            ¬↑p ∣ n ∧\n              ∃ gp,\n                gp.natDegree ≤ p * f.natDegree - 1 ∧\n                  ∀ {r : ℂ},\n                    r ∈ f.aroots ℂ → ‖n • Complex.exp r - p • (Polynomial.aeval r) gp‖ ≤ c ^ p / ↑(p - 1).factorial"
    },
    {
      "name": "Dioph",
      "module_name": "Mathlib.NumberTheory.Dioph",
      "kind": "definition",
      "type": "{α : Type u} → Set (α → ℕ) → Prop"
    },
    {
      "name": "Dioph.abs_poly_dioph",
      "module_name": "Mathlib.NumberTheory.Dioph",
      "kind": "theorem",
      "type": "∀ {α : Type u} (p : Poly α), Dioph.DiophFn fun v => (p v).natAbs"
    },
    {
      "name": "PadicInt.dvd_appr_sub_appr",
      "module_name": "Mathlib.NumberTheory.Padics.RingHoms",
      "kind": "theorem",
      "type": "∀ {p : ℕ} [hp_prime : Fact (Nat.Prime p)] (x : ℤ_[p]) (m n : ℕ), m ≤ n → p ^ m ∣ x.appr n - x.appr m"
    }
  ]
}
